// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts The accounts workers run under (no secrets)
	// (GET /accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// ListChats The owner's chats with the coordinator, the most recently active first
	// (GET /chats)
	ListChats(w http.ResponseWriter, r *http.Request, params ListChatsParams)
	// CreateChat Start a chat with the coordinator
	// (POST /chats)
	CreateChat(w http.ResponseWriter, r *http.Request)
	// GetChat A chat, and whether the coordinator is working on it
	// (GET /chats/{chat_id})
	GetChat(w http.ResponseWriter, r *http.Request, chatId ChatID)
	// AbortChat Stop the coordinator's current turn in this chat; nothing happens when it is idle
	// (POST /chats/{chat_id}/abort)
	AbortChat(w http.ResponseWriter, r *http.Request, chatId ChatID)
	// ListChatMessages A chat's messages after a cursor, oldest first; optionally wait for the next one
	// (GET /chats/{chat_id}/messages)
	ListChatMessages(w http.ResponseWriter, r *http.Request, chatId ChatID, params ListChatMessagesParams)
	// SendChatMessage Write to the coordinator; it gets the message when it can take it
	// (POST /chats/{chat_id}/messages)
	SendChatMessage(w http.ResponseWriter, r *http.Request, chatId ChatID)
	// StreamChat A chat as Server-Sent Events, resumable with Last-Event-ID
	// (GET /chats/{chat_id}/stream)
	StreamChat(w http.ResponseWriter, r *http.Request, chatId ChatID, params StreamChatParams)
	// ListDispatchItems A worker's transcript during one Dispatch, oldest first; optionally wait for the next item
	// (GET /dispatches/{dispatch_id}/items)
	ListDispatchItems(w http.ResponseWriter, r *http.Request, dispatchId string, params ListDispatchItemsParams)
	// ListEvents Events after a cursor, oldest first; optionally wait for the next one
	// (GET /events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// StreamEvents Events as Server-Sent Events, resumable with Last-Event-ID
	// (GET /events/stream)
	StreamEvents(w http.ResponseWriter, r *http.Request, params StreamEventsParams)
	// ListGitHosts The git hosts a Run can be on; github.com and gitlab.com are always among them
	// (GET /hosts)
	ListGitHosts(w http.ResponseWriter, r *http.Request)
	// DeleteGitHost Forget a declared host; refused while an open Run or a registered repository is on it
	// (DELETE /hosts/{host})
	DeleteGitHost(w http.ResponseWriter, r *http.Request, host string)
	// PutGitHost Declare a company's git server and its kind; only the owner
	// (PUT /hosts/{host})
	PutGitHost(w http.ResponseWriter, r *http.Request, host string)
	// DeleteGitHostToken Forget a git host's token; only the owner
	// (DELETE /hosts/{host}/token)
	DeleteGitHostToken(w http.ResponseWriter, r *http.Request, host string)
	// PutGitHostToken Keep a token for a git host, replacing the one it had; only the owner
	// (PUT /hosts/{host}/token)
	PutGitHostToken(w http.ResponseWriter, r *http.Request, host string)
	// ListMachineProviders The providers a machine can be created at (owner only)
	// (GET /machine-providers)
	ListMachineProviders(w http.ResponseWriter, r *http.Request)
	// GetMe The token making the request
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListModels Every model, with its provider and the provider's kind
	// (GET /models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// ListNodes The machines that run workers
	// (GET /nodes)
	ListNodes(w http.ResponseWriter, r *http.Request)
	// CreateNode Add a node (owner only). Without a provider its token is in this answer and nowhere else; with one, a machine is created at the provider and installs the node itself
	// (POST /nodes)
	CreateNode(w http.ResponseWriter, r *http.Request)
	// RemoveNode Remove a node that runs no Dispatch; its tokens stop working (owner only)
	// (DELETE /nodes/{node_id})
	RemoveNode(w http.ResponseWriter, r *http.Request, nodeId NodeID)
	// DrainNode Stop new work on a node; what it runs goes on (owner only)
	// (POST /nodes/{node_id}/drain)
	DrainNode(w http.ResponseWriter, r *http.Request, nodeId NodeID)
	// ResumeNode Let a node take new work again (owner only)
	// (POST /nodes/{node_id}/resume)
	ResumeNode(w http.ResponseWriter, r *http.Request, nodeId NodeID)
	// ListProfiles Every profile, at its current version
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// GetProfile A profile at its current version
	// (GET /profiles/{name})
	GetProfile(w http.ResponseWriter, r *http.Request, name Name)
	// ApplyProfile Store a profile's YAML; a changed source makes a new version
	// (PUT /profiles/{name})
	ApplyProfile(w http.ResponseWriter, r *http.Request, name Name)
	// ListProfileVersions A profile's versions, newest first
	// (GET /profiles/{name}/versions)
	ListProfileVersions(w http.ResponseWriter, r *http.Request, name Name)
	// ListProviders The sources of models, with the models each offers
	// (GET /providers)
	ListProviders(w http.ResponseWriter, r *http.Request)
	// ApplyProvider Store a provider's YAML and the models it offers
	// (PUT /providers/{name})
	ApplyProvider(w http.ResponseWriter, r *http.Request, name Name)
	// ListQuestions Questions from workers, in the order they were asked
	// (GET /questions)
	ListQuestions(w http.ResponseWriter, r *http.Request, params ListQuestionsParams)
	// GetQuestion One question
	// (GET /questions/{question_id})
	GetQuestion(w http.ResponseWriter, r *http.Request, questionId QuestionID)
	// AnswerQuestion Answer a question; the first answer wins
	// (POST /questions/{question_id}/answer)
	AnswerQuestion(w http.ResponseWriter, r *http.Request, questionId QuestionID)
	// ForwardQuestion Pass a question addressed to the coordinator on to the owner
	// (POST /questions/{question_id}/forward)
	ForwardQuestion(w http.ResponseWriter, r *http.Request, questionId QuestionID)
	// ListRepos The repositories registered under a name
	// (GET /repos)
	ListRepos(w http.ResponseWriter, r *http.Request)
	// DeleteRepo Forget a registered repository; Runs that named it keep their host and path
	// (DELETE /repos/{name})
	DeleteRepo(w http.ResponseWriter, r *http.Request, name Name)
	// PutRepo Register a repository under a name, or change what the name means; only the owner
	// (PUT /repos/{name})
	PutRepo(w http.ResponseWriter, r *http.Request, name Name)
	// ListRuns Runs, newest first
	// (GET /runs)
	ListRuns(w http.ResponseWriter, r *http.Request, params ListRunsParams)
	// CreateRun Create a Run; a coordinator token becomes its coordinator
	// (POST /runs)
	CreateRun(w http.ResponseWriter, r *http.Request, params CreateRunParams)
	// GetRun A Run with its Tasks and each Task's latest Dispatch
	// (GET /runs/{run_id})
	GetRun(w http.ResponseWriter, r *http.Request, runId RunID)
	// CancelRun Cancel a Run and every Task in it that has not ended
	// (POST /runs/{run_id}/cancel)
	CancelRun(w http.ResponseWriter, r *http.Request, runId RunID)
	// FinishRun Close a Run whose Tasks have all ended
	// (POST /runs/{run_id}/finish)
	FinishRun(w http.ResponseWriter, r *http.Request, runId RunID)
	// CreateTasks Add Tasks to an open Run, with their dependencies
	// (POST /runs/{run_id}/tasks)
	CreateTasks(w http.ResponseWriter, r *http.Request, runId RunID, params CreateTasksParams)
	// ListTasks The Tasks a board shows, most recently changed first
	// (GET /tasks)
	ListTasks(w http.ResponseWriter, r *http.Request, params ListTasksParams)
	// GetTask A Task with its latest Dispatch
	// (GET /tasks/{task_id})
	GetTask(w http.ResponseWriter, r *http.Request, taskId TaskID)
	// CancelTask Cancel a Task; a running worker is stopped first
	// (POST /tasks/{task_id}/cancel)
	CancelTask(w http.ResponseWriter, r *http.Request, taskId TaskID)
	// ReopenTask Give a failed Task, or one waiting for a login, a new start
	// (POST /tasks/{task_id}/reopen)
	ReopenTask(w http.ResponseWriter, r *http.Request, taskId TaskID)
}

