// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts The accounts workers run under (no secrets)
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// ListChats The owner's chats with the coordinator, the most recently active first
	// (GET /chats)
	ListChats(ctx context.Context, request ListChatsRequestObject) (ListChatsResponseObject, error)
	// CreateChat Start a chat with the coordinator
	// (POST /chats)
	CreateChat(ctx context.Context, request CreateChatRequestObject) (CreateChatResponseObject, error)
	// GetChat A chat, and whether the coordinator is working on it
	// (GET /chats/{chat_id})
	GetChat(ctx context.Context, request GetChatRequestObject) (GetChatResponseObject, error)
	// AbortChat Stop the coordinator's current turn in this chat; nothing happens when it is idle
	// (POST /chats/{chat_id}/abort)
	AbortChat(ctx context.Context, request AbortChatRequestObject) (AbortChatResponseObject, error)
	// ListChatMessages A chat's messages after a cursor, oldest first; optionally wait for the next one
	// (GET /chats/{chat_id}/messages)
	ListChatMessages(ctx context.Context, request ListChatMessagesRequestObject) (ListChatMessagesResponseObject, error)
	// SendChatMessage Write to the coordinator; it gets the message when it can take it
	// (POST /chats/{chat_id}/messages)
	SendChatMessage(ctx context.Context, request SendChatMessageRequestObject) (SendChatMessageResponseObject, error)
	// StreamChat A chat as Server-Sent Events, resumable with Last-Event-ID
	// (GET /chats/{chat_id}/stream)
	StreamChat(ctx context.Context, request StreamChatRequestObject) (StreamChatResponseObject, error)
	// ListDispatchItems A worker's transcript during one Dispatch, oldest first; optionally wait for the next item
	// (GET /dispatches/{dispatch_id}/items)
	ListDispatchItems(ctx context.Context, request ListDispatchItemsRequestObject) (ListDispatchItemsResponseObject, error)
	// ListEvents Events after a cursor, oldest first; optionally wait for the next one
	// (GET /events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// StreamEvents Events as Server-Sent Events, resumable with Last-Event-ID
	// (GET /events/stream)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// ListGitHosts The git hosts a Run can be on; github.com and gitlab.com are always among them
	// (GET /hosts)
	ListGitHosts(ctx context.Context, request ListGitHostsRequestObject) (ListGitHostsResponseObject, error)
	// DeleteGitHost Forget a declared host; refused while an open Run or a registered repository is on it
	// (DELETE /hosts/{host})
	DeleteGitHost(ctx context.Context, request DeleteGitHostRequestObject) (DeleteGitHostResponseObject, error)
	// PutGitHost Declare a company's git server and its kind; only the owner
	// (PUT /hosts/{host})
	PutGitHost(ctx context.Context, request PutGitHostRequestObject) (PutGitHostResponseObject, error)
	// DeleteGitHostToken Forget a git host's token; only the owner
	// (DELETE /hosts/{host}/token)
	DeleteGitHostToken(ctx context.Context, request DeleteGitHostTokenRequestObject) (DeleteGitHostTokenResponseObject, error)
	// PutGitHostToken Keep a token for a git host, replacing the one it had; only the owner
	// (PUT /hosts/{host}/token)
	PutGitHostToken(ctx context.Context, request PutGitHostTokenRequestObject) (PutGitHostTokenResponseObject, error)
	// ListMachineProviders The providers a machine can be created at (owner only)
	// (GET /machine-providers)
	ListMachineProviders(ctx context.Context, request ListMachineProvidersRequestObject) (ListMachineProvidersResponseObject, error)
	// GetMe The token making the request
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListModels Every model, with its provider and the provider's kind
	// (GET /models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)
	// ListNodes The machines that run workers
	// (GET /nodes)
	ListNodes(ctx context.Context, request ListNodesRequestObject) (ListNodesResponseObject, error)
	// CreateNode Add a node (owner only). Without a provider its token is in this answer and nowhere else; with one, a machine is created at the provider and installs the node itself
	// (POST /nodes)
	CreateNode(ctx context.Context, request CreateNodeRequestObject) (CreateNodeResponseObject, error)
	// RemoveNode Remove a node that runs no Dispatch; its tokens stop working (owner only)
	// (DELETE /nodes/{node_id})
	RemoveNode(ctx context.Context, request RemoveNodeRequestObject) (RemoveNodeResponseObject, error)
	// DrainNode Stop new work on a node; what it runs goes on (owner only)
	// (POST /nodes/{node_id}/drain)
	DrainNode(ctx context.Context, request DrainNodeRequestObject) (DrainNodeResponseObject, error)
	// ResumeNode Let a node take new work again (owner only)
	// (POST /nodes/{node_id}/resume)
	ResumeNode(ctx context.Context, request ResumeNodeRequestObject) (ResumeNodeResponseObject, error)
	// ListProfiles Every profile, at its current version
	// (GET /profiles)
	ListProfiles(ctx context.Context, request ListProfilesRequestObject) (ListProfilesResponseObject, error)
	// GetProfile A profile at its current version
	// (GET /profiles/{name})
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// ApplyProfile Store a profile's YAML; a changed source makes a new version
	// (PUT /profiles/{name})
	ApplyProfile(ctx context.Context, request ApplyProfileRequestObject) (ApplyProfileResponseObject, error)
	// ListProfileVersions A profile's versions, newest first
	// (GET /profiles/{name}/versions)
	ListProfileVersions(ctx context.Context, request ListProfileVersionsRequestObject) (ListProfileVersionsResponseObject, error)
	// ListProviders The sources of models, with the models each offers
	// (GET /providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// ApplyProvider Store a provider's YAML and the models it offers
	// (PUT /providers/{name})
	ApplyProvider(ctx context.Context, request ApplyProviderRequestObject) (ApplyProviderResponseObject, error)
	// ListQuestions Questions from workers, in the order they were asked
	// (GET /questions)
	ListQuestions(ctx context.Context, request ListQuestionsRequestObject) (ListQuestionsResponseObject, error)
	// GetQuestion One question
	// (GET /questions/{question_id})
	GetQuestion(ctx context.Context, request GetQuestionRequestObject) (GetQuestionResponseObject, error)
	// AnswerQuestion Answer a question; the first answer wins
	// (POST /questions/{question_id}/answer)
	AnswerQuestion(ctx context.Context, request AnswerQuestionRequestObject) (AnswerQuestionResponseObject, error)
	// ForwardQuestion Pass a question addressed to the coordinator on to the owner
	// (POST /questions/{question_id}/forward)
	ForwardQuestion(ctx context.Context, request ForwardQuestionRequestObject) (ForwardQuestionResponseObject, error)
	// ListRepos The repositories registered under a name
	// (GET /repos)
	ListRepos(ctx context.Context, request ListReposRequestObject) (ListReposResponseObject, error)
	// DeleteRepo Forget a registered repository; Runs that named it keep their host and path
	// (DELETE /repos/{name})
	DeleteRepo(ctx context.Context, request DeleteRepoRequestObject) (DeleteRepoResponseObject, error)
	// PutRepo Register a repository under a name, or change what the name means; only the owner
	// (PUT /repos/{name})
	PutRepo(ctx context.Context, request PutRepoRequestObject) (PutRepoResponseObject, error)
	// ListRuns Runs, newest first
	// (GET /runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// CreateRun Create a Run; a coordinator token becomes its coordinator
	// (POST /runs)
	CreateRun(ctx context.Context, request CreateRunRequestObject) (CreateRunResponseObject, error)
	// GetRun A Run with its Tasks and each Task's latest Dispatch
	// (GET /runs/{run_id})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// CancelRun Cancel a Run and every Task in it that has not ended
	// (POST /runs/{run_id}/cancel)
	CancelRun(ctx context.Context, request CancelRunRequestObject) (CancelRunResponseObject, error)
	// FinishRun Close a Run whose Tasks have all ended
	// (POST /runs/{run_id}/finish)
	FinishRun(ctx context.Context, request FinishRunRequestObject) (FinishRunResponseObject, error)
	// CreateTasks Add Tasks to an open Run, with their dependencies
	// (POST /runs/{run_id}/tasks)
	CreateTasks(ctx context.Context, request CreateTasksRequestObject) (CreateTasksResponseObject, error)
	// ListTasks The Tasks a board shows, most recently changed first
	// (GET /tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// GetTask A Task with its latest Dispatch
	// (GET /tasks/{task_id})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// CancelTask Cancel a Task; a running worker is stopped first
	// (POST /tasks/{task_id}/cancel)
	CancelTask(ctx context.Context, request CancelTaskRequestObject) (CancelTaskResponseObject, error)
	// ReopenTask Give a failed Task, or one waiting for a login, a new start
	// (POST /tasks/{task_id}/reopen)
	ReopenTask(ctx context.Context, request ReopenTaskRequestObject) (ReopenTaskResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

